// Test scenario: Two buffers contain identical string data.
// This path returns 0 == strcmp(self->data, other->data).
// If data is identical, strcmp returns 0, so 0 == 0 evaluates to 1.
void unit_test_buffer_equals_identical_data(void) {
    // Setup: Create two buffers with identical string content
    const char *test_string = "Hello, Unity!";
    buffer_t *buf1 = helper_create_buffer_from_string(test_string);
    buffer_t *buf2 = helper_create_buffer_from_string(test_string);

    // Assert that buffer creation was successful
    TEST_ASSERT_NOT_NULL(buf1);
    TEST_ASSERT_NOT_NULL(buf2);

    // Test: Call the function under test
    int result = buffer_equals(buf1, buf2);

    // Assertions: Verify the expected return value
    TEST_ASSERT_EQUAL_INT(1, result); // Expect 1 (true) because the strings are identical

    // Cleanup: Free allocated memory
    buffer_free(buf1);
    buffer_free(buf2);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_equals_identical_data);
    return UNITY_END();
